	public static void MigrateConfig()
	{
		if (Environment.OSVersion.Platform != PlatformID.Win32NT || Directory.Exists(GetNewDirectory()) || !Directory.Exists(GetOldDirectory()) || new DirectoryInfo(GetOldDirectory()).GetFiles("*.ini").Length < 1 || Directory.Exists(GetNewDirectory()))
		{
			return;
		}
		Directory.CreateDirectory(GetNewDirectory());
		if (Directory.Exists(GetOldDirectory()))
		{
			FileInfo[] files = new DirectoryInfo(GetOldDirectory()).GetFiles("*.ini");
			foreach (FileInfo fileInfo in files)
			{
				fileInfo.CopyTo(Path.Combine(GetNewDirectory(), fileInfo.Name));
			}
		}
	}

	public static void Read(GraphicsDevice dev)
	{
		string[] array;
		if (File.Exists(Path.Combine(OSConfigDir, "config.ini")))
		{
			array = File.ReadAllLines(Path.Combine(OSConfigDir, "config.ini"));
		}
		else
		{
			array = new string[0];
			List<Point> resolutions = VideoOptions.GetResolutions(dev);
			fullScreen = 0;
			if (resolutions.Contains(new Point(1280, 720)))
			{
				displayWidth = 1280;
				displayHeight = 720;
				fullScreen = 2;
			}
			if (resolutions.Contains(new Point(1920, 1080)))
			{
				displayWidth = 1920;
				displayHeight = 1080;
				fullScreen = 2;
			}
			if (resolutions.Contains(new Point(2560, 1440)))
			{
				displayWidth = 2560;
				displayHeight = 1440;
				fullScreen = 2;
			}
			if (resolutions.Contains(new Point(3840, 2160)))
			{
				displayWidth = 3840;
				displayHeight = 2160;
				fullScreen = 2;
			}
			newConfig = true;
		}
		InputMgr.Init();
		string[] array2 = array;
		foreach (string text in array2)
		{
			if (!text.Contains('='))
			{
				continue;
			}
			try
			{
				string[] array3 = text.Split('=');
				switch (array3[0])
				{
				case "display_width":
					displayWidth = Convert.ToInt32(array3[1]);
					break;
				case "display_height":
					displayHeight = Convert.ToInt32(array3[1]);
					break;
				case "fullscreen":
					fullScreen = Convert.ToInt32(array3[1]);
					break;
				case "vsync":
					vSync = Convert.ToInt32(array3[1]);
					break;
				case "sfx":
					sfx = Convert.ToInt32(array3[1]);
					break;
				case "debug":
					debug = Convert.ToInt32(array3[1]);
					break;
				case "bgm":
					bgm = Convert.ToInt32(array3[1]);
					break;
				case "screenshake":
					screenshake = Convert.ToInt32(array3[1]);
					break;
				case "disableinput":
					disableInput = Convert.ToInt32(array3[1]);
					break;
				case "frameratecap":
					frameRateCap = Convert.ToInt32(array3[1]);
					if (frameRateCap < 60)
					{
						frameRateCap = 60;
					}
					if (frameRateCap > 360)
					{
						frameRateCap = 360;
					}
					break;
				case "lastsave":
					lastSave = Convert.ToInt32(array3[1]);
					break;
				case "blood":
					bloodGore = Convert.ToInt32(array3[1]);
					break;
				case "hide_helmet":
					hideHelmet = Convert.ToInt32(array3[1]);
					break;
				case "language":
					language = Convert.ToInt32(array3[1]);
					if (language < 0 || language >= 13)
					{
						language = 0;
					}
					Game1.language = language;
					if (Game1.language == 6)
					{
						buttonConfig = 1;
					}
					break;
				case "vibration":
					vibration = Convert.ToInt32(array3[1]);
					break;
				case "hudsize":
					hudSize = Convert.ToInt32(array3[1]);
					break;
				case "hudvis":
					hudVis = Convert.ToInt32(array3[1]);
					break;
				case "mouse_control":
					mouseControl = Convert.ToInt32(array3[1]);
					break;
				case "buttonconfig":
					buttonConfig = Convert.ToInt32(array3[1]);
					break;
				case "gamepadicons":
					gamepadIcons = Convert.ToInt32(array3[1]);
					break;
				case "ugclist":
					ugcList = array3[1];
					break;
				case "migrated":
					migrated = Convert.ToInt32(array3[1]);
					break;
				}
				InputMgr.ReadConfigLine(array3[0], array3[1]);
			}
			catch
			{
			}
		}
	}

