	public DialogNode(DialogNode dialogNode)
	{
		name = dialogNode.name;
		text = new TextSeries[dialogNode.text.Length];
		for (int i = 0; i < text.Length; i++)
		{
			text[i].text = dialogNode.text[i].text;
		}
		option = new NodeOption[5];
		for (int j = 0; j < 5; j++)
		{
			option[j] = new NodeOption(dialogNode.option[j]);
		}
		precheckFlagStr = new string[dialogNode.precheckFlagStr.Length];
		precheckFlagGoto = new string[dialogNode.precheckFlagGoto.Length];
		for (int k = 0; k < 4; k++)
		{
			precheckFlagStr[k] = dialogNode.precheckFlagStr[k];
			precheckFlagGoto[k] = dialogNode.precheckFlagGoto[k];
		}
		postSetFlagStr = dialogNode.postSetFlagStr;
		postGoto = dialogNode.postGoto;
		giveScript = dialogNode.giveScript;
		storeScript = dialogNode.storeScript;
	}

	internal void Read(BinaryReader reader)
	{
		name = reader.ReadString();
		this.text = new TextSeries[13];
		for (int i = 0; i < 13; i++)
		{
			this.text[i] = new TextSeries();
			string text = reader.ReadString();
			if (text == "")
			{
				this.text[i].text = null;
			}
			else if (i == 6)
			{
				if (text.StartsWith(">") && text.Length > 1)
				{
					text = text.Substring(1);
				}
				this.text[i].text = text.Split('>');
			}
			else
			{
				this.text[i].text = text.Split('\n');
			}
		}
		precheckFlagStr = new string[4];
		precheckFlagGoto = new string[4];
		List<NodeOption> list = new List<NodeOption>();
		for (int j = 0; j < 5; j++)
		{
			NodeOption nodeOption = new NodeOption();
			nodeOption.Read(reader);
			if (nodeOption.text[0] != "")
			{
				list.Add(nodeOption);
			}
		}
		if (list.Count > 0)
		{
			option = list.ToArray();
		}
		else
		{
			option = null;
		}
		for (int k = 0; k < 4; k++)
		{
			precheckFlagStr[k] = reader.ReadString();
			precheckFlagGoto[k] = reader.ReadString();
		}
		postSetFlagStr = reader.ReadString();
		postGoto = reader.ReadString();
		string text2 = reader.ReadString();
		if (text2 != "")
		{
			giveScript = text2.Split('\r');
			text2 = "";
			string[] array = giveScript;
			foreach (string text3 in array)
			{
				text2 += text3;
			}
			giveScript = text2.Split('\n');
		}
		else
		{
			giveScript = null;
		}
		text2 = reader.ReadString();
		if (text2 != "")
		{
			storeScript = text2.Split('\r');
			text2 = "";
			string[] array = storeScript;
			foreach (string text4 in array)
			{
				text2 += text4;
			}
			storeScript = text2.Split('\n');
		}
		else
		{
			storeScript = null;
