namespace DialogEdit.glyphrender;

public class GlyphData
{
	public Glyph[] glyphList;

	public int[] glyphMap;

	public GlyphData(string path)
	{
		BinaryReader binaryReader = new BinaryReader(File.Open(path, FileMode.Open, FileAccess.Read));
		int num = 0;
		int num2 = binaryReader.ReadInt32();
		glyphList = new Glyph[num2];
		for (int i = 0; i < num2; i++)
		{
			glyphList[i] = new Glyph(binaryReader, i);
			if (glyphList[i].idx > num)
			{
				num = glyphList[i].idx;
			}
		}
		glyphMap = new int[num + 1];
		for (int j = 0; j < glyphMap.Length; j++)
		{
			glyphMap[j] = -1;
		}
		for (int k = 0; k < glyphList.Length; k++)
		{
			glyphMap[glyphList[k].idx] = k;
		}
		binaryReader.Close();
	}

	internal Glyph GetGlyph(char p)
	{
		if (p >= glyphMap.Length)
		{
			return null;
		}
		if (glyphMap[(uint)p] == -1)
		{
			return null;
		}
		return glyphList[glyphMap[(uint)p]];
	}

	internal float GetGlyphLength(char p)
	{
		return GetGlyph(p)?.width ?? 0f;
	}
}

