	public const float MAX_FRAME = 29f;

	private bool demoBottle;

	public const string DEMO_OWNER = "!@#D3MO!@#";

	public void Update(bool canOnline)
	{
		if (seen && !demoBottle)
		{
			_ = demoBottle;
		}
		if (seen || demoBottle)
		{
			frame -= Game1.frameTime;
		}
		if (frame <= 0f)
		{
			active = false;
		}
		if (!canOnline && sender != "!@#D3MO!@#")
		{
			active = false;
		}
	}

	public void Draw()
	{
		float a = 1f;
		if (frame > 28f)
		{
			a = 29f - frame;
		}
		if (frame < 1f)
		{
			a = frame;
		}
		if (Textures.tex[Consumables.consumableTexIdx].IsLoaded())
		{
			Vector2 screenLoc = ScrollManager.GetScreenLoc(loc + new Vector2(0f, -12f), 0);
			if (screenLoc.X > 0f && screenLoc.Y > 0f && screenLoc.X < ScrollManager.screenSize.X && screenLoc.Y < ScrollManager.screenSize.Y)
			{
				Textures.tex[Consumables.consumableTexIdx].Draw(screenLoc, 30, new Vector2(1f, 1f) * 0.5f * ScrollManager.cannedDepth[0], 0f, 1f, 1f, 1f, a);
				seen = true;
			}
			else if (DebugMgr.showBottlesBeyondBounds)
			{
				float angle = Trig.GetAngle(screenLoc, ScrollManager.screenSize / 2f);
				screenLoc = ScrollManager.screenSize / 2f + new Vector2((float)Math.Cos(angle), (float)Math.Sin(angle)) * ScrollManager.screenSize.Y * 0.3f;
				SpriteTools.sprite.Draw(InterfaceRender.interfaceTex, screenLoc, new Rectangle(576, 128, 64, 64), (!seen) ? new Color(0f, 1f, 0f, frame) : new Color(1f, 0f, 0f, frame), angle, new Vector2(32f, 32f), 1f, SpriteEffects.None, 1f);
			}
		}
	}

