	{
		sender = owner;
		this.loc = loc;
		this.message = message;
		this.recipient = recipient;
		this.votes = votes;
		active = true;
		this.frame = frame;
		seen = false;
		demoBottle = sender == "!@#D3MO!@#";
		if (!demoBottle && SteamServiceMgr.verbose)
		{
