namespace ProjectTower.gameservices.messages;

public class BottleMessageMgr
{
	public static BottleMessage[] bottleMessage;

	private static int totalBottleMessages;

	public const int MAX_CHARS = 100;

	public const int TOTAL_BOTTLE_MESSAGES = 20;

	public static void Init()
	{
		bottleMessage = new BottleMessage[20];
		for (int i = 0; i < bottleMessage.Length; i++)
		{
			bottleMessage[i] = new BottleMessage();
		}
	}

	public static void AddMessage(string owner, Vector2 loc, string message, string recipient, int votes, float frame)
	{
		if (!Monitor.TryEnter(bottleMessage, 1000))
		{
			return;
		}
		try
		{
			for (int i = 0; i < bottleMessage.Length; i++)
			{
				if (bottleMessage[i].active && bottleMessage[i].loc == loc)
				{
					return;
				}
			}
			for (int j = 0; j < bottleMessage.Length; j++)
			{
				if (!bottleMessage[j].active)
				{
					bottleMessage[j].Init(owner, loc, message, recipient, votes, frame);
					if (j >= totalBottleMessages)
					{
						totalBottleMessages = j + 1;
					}
					break;
				}
			}
		}
		finally
		{
			Monitor.Exit(bottleMessage);
		}
	}

	public static void Draw()
	{
		if (!Monitor.TryEnter(bottleMessage, 1000))
		{
			return;
		}
		try
		{
			for (int i = 0; i < totalBottleMessages; i++)
			{
				if (bottleMessage[i].active)
				{
					bottleMessage[i].Draw();
				}
			}
		}
		finally
		{
			Monitor.Exit(bottleMessage);
		}
	}

	public static void SetSeen()
	{
		for (int i = 0; i < bottleMessage.Length; i++)
		{
			if (bottleMessage[i].active)
			{
				bottleMessage[i].seen = true;
			}
		}
	}

	public static void UpdateMessages()
	{
		bool onlineCapable = PlayerMgr.GetOnlineCapable();
		for (int i = 0; i < totalBottleMessages; i++)
		{
			if (bottleMessage[i].active)
			{
				bottleMessage[i].Update(onlineCapable);
			}
		}
		if (totalBottleMessages > 0 && !bottleMessage[totalBottleMessages - 1].active)
		{
			totalBottleMessages--;
		}
	}

	internal static void Clear()
	{
		totalBottleMessages = 0;
	}

	internal static int GetBottle(Character c)
	{
		float num = 100f;
		for (int i = 0; i < totalBottleMessages; i++)
		{
			if (bottleMessage[i].active && c.loc.Y < bottleMessage[i].loc.Y + 32f && c.loc.Y > bottleMessage[i].loc.Y - 64f)
			{
				if (c.loc.X < bottleMessage[i].loc.X && c.face == 1 && c.loc.X > bottleMessage[i].loc.X - num)
				{
					return i;
				}
				if (c.loc.X > bottleMessage[i].loc.X && c.face == 0 && c.loc.X < bottleMessage[i].loc.X + num)
				{
					return i;
				}
			}
		}
		return -1;
	}
}
