	p.dialog.dialogCatIdx = dialogIdx;
	p.dialog.dialogCatNodeIdx = nodeIdx;
	if (dialogNode.postSetFlagStr != "")
	{
		PlayerMgr.SetMainPlayerFlag(dialogNode.postSetFlagStr);
	}
	if (dialogNode.text[Game1.language].text != null)
	{
		p.dialog.talkieFrame = 0f;
		p.dialog.Activate(dialogNode.text[Game1.language].text, npcIdx);
	}
	else if (dialogNode.option != null)
