	p.dialog.active = false;
	PlayerMgr.CloseCoopPlayers(p);
	Character playerCharacter = CharMgr.GetPlayerCharacter(p);
	if (playerCharacter != null)
	{
		if (playerCharacter.anim.animName == "pray" && !(p.runeGetFrame > 0f))
		{
